import pandas as pd, numpy as np, statsmodels.formula.api as smf, patsy
df=pd.read_csv('data.csv')
controls = 'log_pre_gmv + orders + cat_share + tenure + C(region) + C(tier) + dY_placebo'
# Fit additive splines for D and log_hist_days
for dfD in [3,4,5]:
    for dfH in [3,4,5]:
        formula=f'dY ~ bs(D, df={dfD}) + bs(log_hist_days, df={dfH}) + {controls}'
        try:
            m=smf.ols(formula, df).fit(cov_type='HC1')
            print('dfD',dfD,'dfH',dfH,'R2',m.rsquared,'AIC',m.aic)
        except Exception as e:
            print('err',e)

